// #343d8d נתוני הדגמה מתמשכים, ליטוש ופרסום Preview. Кейсы: .qa/tests/preview-demo/PD-01..PD-M1. План: specs/preview-demo.md.
// Гость → демо-вход (без пароля). Только чтение, данные не создаются. @prod-safe.
// Preview — другой хост: URL из PREVIEW_URL, абсолютные ссылки; основной staging — baseURL конфига.
// Не проверяем точное число тендеров и даты (сид относительный, протухает после 28.11.2026).
import { test, expect, Page } from '@playwright/test';

const PREVIEW = (process.env.PREVIEW_URL || 'https://tenderflow-web-staging-obpygl1k7-aviels-projects.vercel.app').replace(/\/+$/, '');
const MAIN = (process.env.QA_BASE_URL || 'https://tenderflow-web-staging.vercel.app').replace(/\/+$/, '');
const DEMO_BTN = 'כניסה לסביבת ההדגמה';
const OLD_NAME = /Tenderflow\s*IL/i;
const TABS = ['סקירה ומועדים', 'תנאי סף ודגלים אדומים', 'מרכז מסמכים', 'משימות ושאלות הבהרה', 'תיק הגשה'];
const PROFILE_TABS = ['פרטי חברה', 'מידע להתאמת מכרזים', 'גורמים מקצועיים', 'מסמכים קבועים'];

test.use({ serviceWorkers: 'block' });

const demoButton = (page: Page) => page.getByText(DEMO_BTN).first();
const tenderLinks = (page: Page) => page.locator('a[href*="/analysis"]');

/** Видимый текст + title + innerText: старого названия нет. */
async function expectNoOldName(page: Page, where: string) {
  const t = await page.evaluate(() => document.title + '\n' + document.body.innerText);
  expect(OLD_NAME.test(t), `«Tenderflow IL» не должно быть: ${where}`).toBe(false);
}

async function demoLogin(page: Page) {
  await page.goto(PREVIEW + '/login');
  await demoButton(page).click();
  await expect(page).not.toHaveURL(/\/login/);
  await expect(page.getByText('נתוני הדגמה').first()).toBeVisible();
  await expect(tenderLinks(page).first()).toBeVisible();
}

async function feedTitles(page: Page): Promise<string[]> {
  await page.goto(PREVIEW + '/');
  await expect(tenderLinks(page).first()).toBeVisible();
  const titles = await tenderLinks(page).evaluateAll((a) =>
    [...new Set(a.map((x) => (x as HTMLElement).innerText.trim()).filter((t) => t.length > 12 && !/התחל/.test(t)))].sort(),
  );
  expect(titles.length, 'в фиде есть тендеры').toBeGreaterThan(0);
  return titles;
}

const hScroll = (page: Page) =>
  page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

test.describe('Preview демо-среда (#343d8d)', () => {
  test('PD-01 анонимный заход остаётся на хосте Preview, виден демо-вход #343d8d @desktop @prod-safe', async ({ page }) => {
    await page.goto(PREVIEW + '/');
    await expect(demoButton(page)).toBeVisible();
    const host = new URL(PREVIEW).host;
    expect(new URL(page.url()).host, 'хост не изменился (нет Vercel SSO)').toBe(host);
    await expect(page.getByRole('button', { name: 'כניסה לטרמינל' })).toBeVisible();
  });

  test('PD-02 экран входа: title и текст TAQO, нет «Tenderflow IL» #343d8d @desktop @prod-safe', async ({ page }) => {
    await page.goto(PREVIEW + '/login');
    await expect(demoButton(page)).toBeVisible();
    await expect(page).toHaveTitle(/TAQO/);
    await expect(page.getByText('TAQO').first()).toBeVisible();
    await expectNoOldName(page, '/login Preview');
  });

  test('PD-03 демо-вход → фид с «נתוני הדגמה» и тендерами #343d8d @desktop @prod-safe', async ({ page }) => {
    await demoLogin(page);
    await expect(page).toHaveTitle(/TAQO/);
    await expectNoOldName(page, 'фид');
  });

  test('PD-04 тендер: баннер «נתוני הדגמה שמורים…» на всех 5 вкладках #343d8d @desktop @prod-safe', async ({ page }) => {
    await demoLogin(page);
    const href = await tenderLinks(page).first().getAttribute('href');
    expect(href).toBeTruthy();
    await page.goto(new URL(href!, PREVIEW + '/').toString());
    for (const name of TABS) {
      await page.getByRole('tab', { name }).or(page.getByRole('button', { name, exact: true })).or(page.getByText(name, { exact: true })).first().click();
      await expect(page.getByText(/נתוני הדגמה שמורים/).first(), `баннер на вкладке «${name}»`).toBeVisible();
      await expectNoOldName(page, `вкладка «${name}»`);
    }
  });

  test('PD-05 профиль компании: «אופק מערכות — הדגמה», нет «Tenderflow IL» #343d8d @desktop @prod-safe', async ({ page }) => {
    await demoLogin(page);
    await page.goto(PREVIEW + '/onboarding');
    await expect(page.getByText('אופק מערכות').first()).toBeVisible();
    for (const name of PROFILE_TABS) {
      await page.getByText(name, { exact: false }).first().click();
      await expectNoOldName(page, `профиль, вкладка «${name}»`);
    }
  });

  test('PD-06 сохранность: после reload и выхода/входа те же тендеры #343d8d @desktop @prod-safe', async ({ page }) => {
    await demoLogin(page);
    const before = await feedTitles(page);

    await page.reload();
    await expect(page.getByText('נתוני הדגמה').first()).toBeVisible();
    expect(await feedTitles(page), 'после reload').toEqual(before);

    await page.getByRole('button', { name: 'חשבון' }).or(page.getByText('נל', { exact: true })).first().click();
    await page.getByText(/התנתק|יציאה/).first().click();
    await expect(page).toHaveURL(/\/login/);
    await expect(demoButton(page)).toBeVisible();
    await demoButton(page).click();
    await expect(page).not.toHaveURL(/\/login/);
    expect(await feedTitles(page), 'после выхода и повторного входа').toEqual(before);
    await page.goto(PREVIEW + '/onboarding');
    await expect(page.getByText('אופק מערכות').first()).toBeVisible();
  });

  test('PD-07 основной staging: нет демо-входа, есть TAQO, нет «Tenderflow IL» #343d8d @desktop @prod-safe', async ({ page }) => {
    await page.goto(MAIN + '/login');
    await expect(page.getByRole('button', { name: 'כניסה לטרמינל' })).toBeVisible();
    await expect(page.getByText('TAQO').first()).toBeVisible();
    await expect(page.getByText(DEMO_BTN)).toHaveCount(0);
    await expectNoOldName(page, '/login основного staging');
  });

  test('PD-M1 390: нет горизонтальной прокрутки на login, фиде, тендере, профиле #343d8d @mobile @prod-safe', async ({ page }) => {
    await page.goto(PREVIEW + '/login');
    await expect(demoButton(page)).toBeVisible();
    expect(await hScroll(page), 'login').toBeLessThanOrEqual(0);
    await demoLogin(page);
    expect(await hScroll(page), 'фид').toBeLessThanOrEqual(0);
    const href = await tenderLinks(page).first().getAttribute('href');
    await page.goto(new URL(href!, PREVIEW + '/').toString());
    await expect(page.getByText(/נתוני הדגמה שמורים/).first()).toBeVisible();
    expect(await hScroll(page), 'тендер').toBeLessThanOrEqual(0);
    await page.goto(PREVIEW + '/onboarding');
    await expect(page.getByText('אופק מערכות').first()).toBeVisible();
    expect(await hScroll(page), 'профиль').toBeLessThanOrEqual(0);
  });
});
